liz: snippet draft:

```javascript
const fetch = require('node-fetch');
async function callWithRetries(body) {
  const url = 'https://api.redwood.ai/v1/generate';
  let attempt = 0;
  while (attempt < 6) {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${process.env.TOKEN}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    if (res.status === 429) {
      const retryAfter = parseInt(res.headers.get('Retry-After') || '2', 10);
      const backoff = Math.min(30000, Math.pow(2, attempt) * 1000 + retryAfter * 1000);
      await new Promise(r => setTimeout(r, backoff));
      attempt += 1;
      continue;
    }
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  }
  throw new Error('max retries exceeded');
}
```

